import * as THREE from 'three';
import {buildWorld} from './world.js';
import {RaceAudio} from './audio.js';
import {CinematicFX} from './postfx.js';

const $=id=>document.getElementById(id);
const clamp=THREE.MathUtils.clamp, lerp=THREE.MathUtils.lerp;
const wrap=(s,l)=>((s%l)+l)%l;
const ease=(a,b,k,dt)=>lerp(a,b,1-Math.exp(-k*dt));
const fmt=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(2).padStart(5,'0')}`;
const scene=new THREE.Scene();
scene.fog=new THREE.FogExp2(0x5d6385,.00175);
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(error){$('scene').innerHTML='<div style="padding:40px;color:white">This race needs WebGL 2. Please enable hardware acceleration and reload in a current browser.</div>';$('start-button').disabled=true;throw error;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));
renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.1;
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const cinematic=new CinematicFX(THREE,renderer);
$('scene').append(renderer.domElement);
renderer.domElement.setAttribute('aria-label','3D harbor city racing circuit');
const camera=new THREE.PerspectiveCamera(60,innerWidth/innerHeight,.2,1700);
scene.add(new THREE.HemisphereLight(0xb4ccff,0x35243c,2.3));
const sun=new THREE.DirectionalLight(0xffb8a0,3.2);
sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-65,right:65,top:65,bottom:-65,near:1,far:230});sun.shadow.bias=-.001;sun.shadow.normalBias=.07;scene.add(sun,sun.target);
const sky=new THREE.Mesh(new THREE.SphereGeometry(1600,32,16),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{top:{value:new THREE.Color('#212f58')},bottom:{value:new THREE.Color('#feb091')}},vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'uniform vec3 top;uniform vec3 bottom;varying vec3 p;void main(){float h=normalize(p).y;vec3 c=mix(bottom,top,smoothstep(-.04,.58,h));vec3 d=normalize(p);float sun=pow(max(0.,dot(d,normalize(vec3(-.7,.12,-1.)))),1000.);c+=vec3(1.,.55,.22)*sun*2.;gl_FragColor=vec4(c,1.);}'}));
scene.add(sky);
// A procedural studio sky gives the original cars soft metallic reflections.
const envScene=new THREE.Scene();envScene.background=new THREE.Color(0x536582);envScene.add(new THREE.HemisphereLight(0xffffff,0x3c3244,3));
for(const [x,y,z,c] of [[0,15,0,0xdbe8ff],[-12,4,-8,0xffb58d],[14,2,4,0x5bd8ff]]){const panel=new THREE.Mesh(new THREE.PlaneGeometry(20,12),new THREE.MeshBasicMaterial({color:c,side:THREE.DoubleSide}));panel.position.set(x,y,z);panel.lookAt(0,0,0);envScene.add(panel);}
const pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(envScene,.08,.1,100).texture;pmrem.dispose();
const world=buildWorld(THREE,scene);
const playerCar=world.createCar(0x49aaff);scene.add(playerCar);
const rivals=['SORA','KAI','NOVA','MILO','LEX'].map((name,i)=>{const car=world.createCar([0xff6347,0xebc944,0xa584f4,0x45e7bc,0xf0e8d8][i]);scene.add(car);return {name,car,s:8+i*9,x:[-6,5,-1,-7,6][i],speed:0,base:63+i*1.8,finish:0};});
const traffic=Array.from({length:17},(_,i)=>{const car=world.createCar([0x647c8d,0xcdd5dc,0x925b51,0x40535c][i%4]);car.scale.set(.93,1.16,.92);scene.add(car);return {car,s:150+i*world.length/17,x:[-8.7,8.7,-3,3][i%4],speed:23+i%5*3,hit:0};});
const audio=new RaceAudio();let muted=false;
const controls={left:false,right:false,accelerate:false,brake:false,drift:false,nitro:false};
const keys={KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',KeyW:'accelerate',ArrowUp:'accelerate',KeyS:'brake',ArrowDown:'brake',Space:'drift',ShiftLeft:'nitro',ShiftRight:'nitro'};
const state={mode:'menu',s:0,x:0,speed:0,xv:0,y:0,vy:0,air:false,nitro:100,damage:0,time:0,checkpoint:0,drifting:false,boost:false,countdown:3.0,shake:0,driftTime:0,airTime:0,maxSpeed:0,collisions:0,usedNitro:0,boosts:0};
let cameraLook=new THREE.Vector3(), visualYaw=0, lastTime=performance.now(), elapsed=0,lastCount=-1,toastTime=0,collisionCooldown=0,previousRamp=null,finishOrder=[],best=0,frameCost=16,qualityReduced=false;
try{best=Number(localStorage.getItem('afterglow-best'))||0;}catch{}

// Pooled particles and tire marks keep effects bounded during a whole race.
const particleCount=240, pgeo=new THREE.SphereGeometry(1,4,3), pmat=new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.7,depthWrite:false});
const particles=new THREE.InstancedMesh(pgeo,pmat,particleCount);particles.instanceMatrix.setUsage(THREE.DynamicDrawUsage);particles.frustumCulled=false;scene.add(particles);
const pstate=Array.from({length:particleCount},()=>({life:0,pos:new THREE.Vector3(),vel:new THREE.Vector3(),size:0,color:new THREE.Color()}));let pindex=0;const dummy=new THREE.Object3D();
const markMesh=new THREE.InstancedMesh(new THREE.PlaneGeometry(.24,1.5),new THREE.MeshBasicMaterial({color:0x131523,transparent:true,opacity:.44,depthWrite:false}),380);markMesh.frustumCulled=false;scene.add(markMesh);let markIndex=0,markClock=0;
for(let i=0;i<380;i++){dummy.scale.setScalar(0);dummy.updateMatrix();markMesh.setMatrixAt(i,dummy.matrix);}
function emit(pos,color,count=6,force=1){for(let i=0;i<count;i++){const p=pstate[pindex++%particleCount];p.pos.copy(pos);p.vel.set((Math.random()-.5)*8*force,Math.random()*4*force,(Math.random()-.5)*8*force);p.life=.4+Math.random()*.5;p.size=color===0xa6a9bd?.5:.065;p.color.setHex(color);}}
function tickParticles(dt){for(let i=0;i<particleCount;i++){const p=pstate[i];p.life-=dt;if(p.life>0){p.pos.addScaledVector(p.vel,dt);p.vel.y-=dt*3;dummy.position.copy(p.pos);dummy.scale.setScalar(p.size*(1+(1-p.life)*2));particles.setColorAt(i,p.color);}else dummy.scale.setScalar(0);dummy.updateMatrix();particles.setMatrixAt(i,dummy.matrix);}particles.instanceMatrix.needsUpdate=true;if(particles.instanceColor)particles.instanceColor.needsUpdate=true;}
function tireMark(sample){for(const x of [-.88,.88]){dummy.position.copy(sample.position).addScaledVector(sample.right,x);dummy.position.y+=.045;dummy.rotation.set(-Math.PI/2,0,-sample.heading);dummy.scale.set(1,1,1);dummy.updateMatrix();markMesh.setMatrixAt(markIndex++%380,dummy.matrix);}markMesh.instanceMatrix.needsUpdate=true;}

const fx=document.createElement('canvas');fx.id='speed-effects';fx.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:2;mix-blend-mode:screen';document.body.append(fx);const fxctx=fx.getContext('2d');
const speedLines=Array.from({length:32},(_,i)=>({a:i/32*Math.PI*2,r:.65+Math.random()*.3,l:.15+Math.random()*.3}));
function renderSpeedFX(t){fxctx.clearRect(0,0,fx.width,fx.height);if(state.mode!=='racing')return;const intensity=state.boost?1:Math.max(0,(state.speed-65)/60);if(intensity<=0)return;const w=fx.width,h=fx.height;fxctx.lineWidth=1.3;for(const l of speedLines){const r=l.r+Math.sin(t*8+l.a)*.03;const a=l.a;fxctx.strokeStyle=`rgba(170,228,255,${.19*intensity})`;fxctx.beginPath();fxctx.moveTo(w/2+Math.cos(a)*w*r*.46,h*.43+Math.sin(a)*h*r*.58);fxctx.lineTo(w/2+Math.cos(a)*w*(r+l.l)*.5,h*.43+Math.sin(a)*h*(r+l.l)*.6);fxctx.stroke();}}
const vignette=document.createElement('div');vignette.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse at 55% 40%,transparent 35%,rgba(7,11,25,.4) 100%)';document.body.append(vignette);
function toast(message,duration=2){$('toast').textContent=message;$('toast').hidden=false;toastTime=duration;}
function clearInputs(){for(const key of Object.keys(controls))controls[key]=false;document.querySelectorAll('[data-control]').forEach(b=>b.classList.remove('pressed'));}
function setMode(mode){state.mode=mode;document.body.classList.toggle('racing',['racing','countdown','paused'].includes(mode));$('menu').hidden=mode!=='menu';$('hud').hidden=!['racing','countdown','paused'].includes(mode);$('pause-panel').hidden=mode!=='paused';$('results').hidden=mode!=='results';$('touch-controls').hidden=!['racing','countdown'].includes(mode);$('countdown').hidden=mode!=='countdown';if(mode!=='racing')state.boost=false;audio.pause(mode==='paused'||mode==='menu'||mode==='results');}
function placeCar(car,s,x,y,sway=0){const sample=world.sample(s,x);car.position.copy(sample.position);if(y!==undefined)car.position.y=y;car.rotation.set(0,sample.heading+sway,0);return sample;}
function resetRace(){clearInputs();Object.assign(state,{s:0,x:0,speed:0,xv:0,y:world.surface(0,0),vy:0,air:false,nitro:100,damage:0,time:0,checkpoint:0,drifting:false,boost:false,countdown:3.0,shake:0,driftTime:0,airTime:0,maxSpeed:0,collisions:0,usedNitro:0,boosts:0});collisionCooldown=0;previousRamp=null;finishOrder=[];lastCount=-1;visualYaw=0;markIndex=0;for(let i=0;i<380;i++){dummy.scale.setScalar(0);dummy.updateMatrix();markMesh.setMatrixAt(i,dummy.matrix);}markMesh.instanceMatrix.needsUpdate=true;for(const p of pstate)p.life=0;rivals.forEach((r,i)=>{r.s=8+i*9;r.x=[-6,5,-1,-7,6][i];r.speed=0;r.finish=0;placeCar(r.car,r.s,r.x);});traffic.forEach((r,i)=>{r.s=150+i*world.length/17;r.hit=0;placeCar(r.car,r.s,r.x);});for(const p of world.pickups){p.active=true;p.mesh.visible=true;}for(const b of world.breakables){b.active=true;b.mesh.visible=true;}playerCar.rotation.z=0;placeCar(playerCar,0,0,state.y);setMode('countdown');audio.start();audio.pause(false);toast('HARBOR RUN  /  FINISH FIRST',3);updateHUD();}
function pauseRace(){if(state.mode==='racing'||state.mode==='countdown'){state.resumeMode=state.mode;setMode('paused');clearInputs();}else if(state.mode==='paused'){setMode(state.resumeMode||'racing');audio.pause(false);}}
function showMenu(){setMode('menu');clearInputs();$('toast').hidden=true;placeCar(playerCar,0,0,world.surface(0,0));rivals.forEach((r,i)=>placeCar(r.car,10+i*9,[-6,5,-1,-7,6][i]));}
function finish(){if(state.mode!=='racing')return;const position=1+rivals.filter(r=>r.s>=world.length).length;finishOrder.push({name:'YOU',time:state.time});rivals.filter(r=>!r.finish).forEach(r=>finishOrder.push({name:r.name,time:state.time+(world.length-r.s)/Math.max(1,r.speed)}));finishOrder.sort((a,b)=>a.time-b.time);if(!best||state.time<best){best=state.time;try{localStorage.setItem('afterglow-best',String(best));}catch{}}$('result-title').textContent=position===1?'THE CITY IS YOURS.':'ONE MORE RUN.';$('result-position').textContent=`${position} / 6`;$('result-time').textContent=fmt(state.time);$('result-best').textContent=fmt(best);$('result-detail').textContent=position===1?'1ST PLACE · HARBOR RUN COMPLETE':`P${position} FINISH · Chase the perfect line and use your nitro on the straights.`;let board=$('leaderboard');if(!board){board=document.createElement('div');board.id='leaderboard';board.style.cssText='display:grid;gap:6px;margin:20px 0;font:600 12px monospace;text-align:left';$('result-detail').after(board);}board.replaceChildren(...finishOrder.map((r,i)=>{const row=document.createElement('div');row.style.cssText=`display:flex;justify-content:space-between;gap:32px;padding:7px 12px;background:${r.name==='YOU'?'#d9ff431a':'#ffffff07'};color:${r.name==='YOU'?'#d9ff43':'#b7c3d6'}`;const label=document.createElement('span');label.textContent=`${i+1}   ${r.name}`;const time=document.createElement('span');time.textContent=r.name==='YOU'||r.time<=state.time?fmt(r.time):`+${(r.time-state.time).toFixed(1)}s projected`;row.append(label,time);return row;}));setMode('results');audio.play('finish');clearInputs();}

function collide(force=1){if(collisionCooldown>0)return;collisionCooldown=.65;state.speed*=Math.max(.48,1-.24*force);state.damage=clamp(state.damage+7*force,0,100);state.shake=.3*force;state.collisions++;emit(playerCar.position.clone().add(new THREE.Vector3(0,.5,0)),0xffb94d,20,2);audio.play('collision');}
function updateRace(dt){state.time+=dt;collisionCooldown-=dt;const turn=Number(controls.right)-Number(controls.left), throttle=controls.accelerate, brake=controls.brake;state.drifting=controls.drift&&state.speed>18&&Math.abs(turn)>0;const wasBoost=state.boost;state.boost=controls.nitro&&(state.nitro>8||(wasBoost&&state.nitro>.2))&&state.speed>6&&!brake;if(state.boost&&!wasBoost)state.boosts++;
const cap=state.boost?104:78-state.damage*.035;
if(throttle||state.boost)state.speed+=dt*(state.boost?31:17)*(1-state.speed/(cap*1.35));else state.speed-=dt*(3.1+state.speed*.035);
if(brake)state.speed-=dt*40;if(state.drifting)state.speed-=dt*4;
state.speed=clamp(state.speed,0,cap);state.maxSpeed=Math.max(state.maxSpeed,state.speed*3.6);
if(state.boost){state.nitro=Math.max(0,state.nitro-26*dt);state.usedNitro+=26*dt;}else state.nitro=Math.min(100,state.nitro+dt*(state.drifting?12:1.8));
const here=world.sample(state.s), ahead=world.sample(state.s+8);let curvature=Math.atan2(here.tangent.x*ahead.tangent.z-here.tangent.z*ahead.tangent.x,here.tangent.dot(ahead.tangent))/8;
state.xv=ease(state.xv,turn*(state.drifting?15:10.5)*Math.min(1,state.speed/15)+curvature*state.speed*state.speed*.055,state.drifting?3:7,dt);state.x+=state.xv*dt;
let rightBound=world.outerWidth(state.s)-1.25,leftBound=-world.width/2+1.25;
if(state.x>rightBound||state.x<leftBound){state.x=clamp(state.x,leftBound,rightBound);state.xv*=-.25;if(state.speed>10)collide(.65);}
const express=state.x>15&&world.outerWidth(state.s)>22;
const ds=state.speed*dt*(state.drifting?.97:1)*(express?1.14:1);state.s+=ds;const surface=world.surface(state.s,state.x);let ramp=null;for(const r of world.ramps){const q=wrap(state.s-r.s,world.length);if(q>=0&&q<r.length&&Math.abs(state.x-r.x)<r.width/2)ramp=r;}
if(previousRamp&&!ramp&&!state.air&&state.speed>20){state.air=true;state.vy=clamp(state.speed*previousRamp.height/previousRamp.length,8,16);state.airTime=0;audio.play('jump');toast('AIR TIME  + NITRO',1.4);}previousRamp=ramp;
if(state.air){state.vy-=dt*22;state.y+=state.vy*dt;state.airTime+=dt;state.nitro=Math.min(100,state.nitro+8*dt);if(state.y<=surface){state.y=surface;state.air=false;state.vy=0;state.shake=.18;emit(playerCar.position,0xa6a9bd,12);}}else state.y=surface;
visualYaw=ease(visualYaw,-turn*(state.drifting?.38:.075)-state.xv*.005,8,dt);const sample=placeCar(playerCar,state.s,state.x,state.y,visualYaw);playerCar.rotation.z=ease(playerCar.rotation.z,-turn*(state.drifting?.075:.03),8,dt);playerCar.rotation.x=ease(playerCar.rotation.x,state.air?-state.vy*.018:0,8,dt);
if(state.drifting){state.driftTime+=dt;markClock+=dt;if(markClock>.06&&!state.air){markClock=0;tireMark(sample);const rear=sample.position.clone().addScaledVector(sample.tangent,-1.7);emit(rear,0xa6a9bd,3);}}else if(state.driftTime>1){toast(`DRIFT  +${Math.round(state.driftTime*12)} NITRO`,1);state.driftTime=0;}else state.driftTime=0;
for(const flame of playerCar.userData.flames||[]){flame.visible=state.boost;flame.scale.y=.8+Math.random()*.8;}
playerCar.userData.paint.color.setHex(0x49aaff).multiplyScalar(1-state.damage*.0035);
playerCar.userData.body.scale.y=1-state.damage*.001;
if(state.damage>55&&Math.random()<dt*9)emit(sample.position.clone().addScaledVector(sample.tangent,1.6).add(new THREE.Vector3(0,.9,0)),0xa6a9bd,1);
for(const wheel of playerCar.userData.wheels||[])wheel.rotation.x-=state.speed*dt*2.5;
for(const p of world.pickups){if(p.active&&Math.abs(state.s-p.s)<4.5&&Math.abs(state.x-p.x)<2.3&&state.y-sample.position.y<3){p.active=false;p.mesh.visible=false;state.nitro=Math.min(100,state.nitro+30);audio.play('pickup');toast('NITRO CELL  +30',1.2);emit(p.mesh.position,0x69f2ff,12);}}
for(const b of world.breakables){if(b.active&&Math.abs(state.s-b.s)<3&&Math.abs(state.x-b.x)<1.7&&!state.air){b.active=false;b.mesh.visible=false;emit(b.mesh.position,0xffae65,14,2);state.speed*=.95;audio.play('collision');}}
for(let i=0;i<rivals.length;i++){const r=rivals[i];const target=r.base+Math.sin(state.time*.4+i)*3+(state.s-r.s>180?4:0);r.speed=ease(r.speed,target,.45,dt);r.s+=r.speed*dt;r.x=ease(r.x,Math.sin(r.s*.006+i*3)*7.6,1.5,dt);let obs=traffic.find(t=>{const d=wrap(t.s-r.s,world.length);return d>0&&d<27&&Math.abs(t.x-r.x)<2.7;});if(obs)r.x=ease(r.x,obs.x>0?-5:5,3,dt);placeCar(r.car,r.s,r.x,world.surface(r.s,r.x));for(const wheel of r.car.userData.wheels||[])wheel.rotation.x-=r.speed*dt*2.5;if(r.s>=world.length&&!r.finish){r.finish=state.time;finishOrder.push({name:r.name,time:r.finish});}if(!state.air&&Math.abs(r.s-state.s)<4.2&&Math.abs(r.x-state.x)<2.05){collide(.8);state.x+=(state.x>r.x?1:-1)*.35;}}
for(const t of traffic){t.s=wrap(t.s+t.speed*dt,world.length);t.hit-=dt;placeCar(t.car,t.s,t.x,world.surface(t.s,t.x));const d=Math.abs(wrap(t.s-state.s+world.length/2,world.length)-world.length/2);if(d<4&&Math.abs(t.x-state.x)<2.1&&!state.air&&t.hit<=0){collide(1.2);t.hit=1;}}
const checkpoint=Math.min(4,Math.floor(state.s/world.length*5));if(checkpoint>state.checkpoint){state.checkpoint=checkpoint;toast(`CHECKPOINT ${checkpoint} / 4`,1.7);audio.play('pickup');}
if(state.s>=world.length)finish();
}
function updateHUD(){const rank=1+rivals.filter(r=>r.s>state.s).length;$('position').textContent=rank;$('lap').textContent='1 / 1';$('checkpoint').textContent=`${state.checkpoint} / 4`;$('timer').textContent=fmt(state.time);$('speed').textContent=Math.round(state.speed*3.6).toString().padStart(3,'0');$('gear').textContent=state.speed<2?'N':Math.min(6,Math.floor(state.speed/15)+1);$('nitro-fill').style.width=`${state.nitro}%`;$('damage-fill').style.width=`${state.damage}%`;$('progress-fill').style.width=`${Math.min(100,state.s/world.length*100)}%`;document.body.classList.toggle('boosting',state.boost);drawMap();}
const map=$('minimap'),mapctx=map.getContext('2d');const mapPoints=Array.from({length:150},(_,i)=>world.sample(i/149*world.length).position);const minX=Math.min(...mapPoints.map(p=>p.x)),maxX=Math.max(...mapPoints.map(p=>p.x)),minZ=Math.min(...mapPoints.map(p=>p.z)),maxZ=Math.max(...mapPoints.map(p=>p.z));
function mp(p){const scale=Math.min((map.width-30)/(maxX-minX),(map.height-26)/(maxZ-minZ));return [map.width/2+(p.x-(minX+maxX)/2)*scale,map.height/2+(p.z-(minZ+maxZ)/2)*scale];}
function drawMap(){mapctx.clearRect(0,0,map.width,map.height);mapctx.lineWidth=5;mapctx.strokeStyle='#ffffff25';mapctx.beginPath();mapPoints.forEach((p,i)=>{const [x,y]=mp(p);i?mapctx.lineTo(x,y):mapctx.moveTo(x,y);});mapctx.stroke();mapctx.lineWidth=1;mapctx.strokeStyle='#9aacc0';mapctx.stroke();for(const r of rivals){const [x,y]=mp(world.sample(r.s).position);mapctx.fillStyle='#b5bdd3';mapctx.beginPath();mapctx.arc(x,y,2.2,0,Math.PI*2);mapctx.fill();}for(let i=1;i<5;i++){const [x,y]=mp(world.sample(world.length*i/5).position);mapctx.fillStyle=state.checkpoint>=i?'#d9ff43':'#5da4c8';mapctx.fillRect(x-2,y-2,4,4);}const [sx,sy]=mp(world.sample(0).position);mapctx.fillStyle='white';mapctx.fillRect(sx-3,sy-3,6,6);const [x,y]=mp(world.sample(state.s).position);mapctx.shadowColor='#d9ff43';mapctx.shadowBlur=10;mapctx.fillStyle='#d9ff43';mapctx.beginPath();mapctx.arc(x,y,4,0,Math.PI*2);mapctx.fill();mapctx.shadowBlur=0;}

function updateCamera(dt){const menu=state.mode==='menu';const p=world.sample(menu?0:state.s,menu?0:state.x);let desired,look;if(menu){const angle=Math.sin(elapsed*.1)*.11;desired=p.position.clone().addScaledVector(p.tangent,-10.5).addScaledVector(p.right,-8.5+angle).add(new THREE.Vector3(0,4.4,0));look=p.position.clone().addScaledVector(p.right,-3.5).addScaledVector(p.tangent,2).add(new THREE.Vector3(0,1.1,0));camera.fov=ease(camera.fov,53,3,dt);}else{const boost=state.boost;desired=p.position.clone().addScaledVector(p.tangent,-(boost?10:9)).addScaledVector(p.right,-visualYaw*5);desired.y=state.y+(state.air?5.4:4.3);look=world.sample(state.s+20,state.x*.7).position;look.y=lerp(look.y+1.2,state.y+1.2,.2);camera.fov=ease(camera.fov,boost?79:61+state.speed*.08,4,dt);if(state.shake>0){desired.x+=(Math.random()-.5)*state.shake;desired.y+=(Math.random()-.5)*state.shake;state.shake=Math.max(0,state.shake-dt*.6);}}
camera.position.lerp(desired,1-Math.exp(-dt*(menu?2.5:8)));cameraLook.lerp(look,1-Math.exp(-dt*7));camera.lookAt(cameraLook);camera.rotation.z+=state.drifting?-visualYaw*.06:0;camera.updateProjectionMatrix();sky.position.copy(camera.position);sun.position.copy(playerCar.position).add(new THREE.Vector3(-60,100,-40));sun.target.position.copy(playerCar.position);}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);cinematic.resize(innerWidth,innerHeight,renderer.getPixelRatio());fx.width=innerWidth;fx.height=innerHeight;}window.addEventListener('resize',resize);resize();
function frame(now){requestAnimationFrame(frame);const raw=(now-lastTime)/1000,dt=Math.min(.05,Math.max(0,raw));lastTime=now;elapsed+=dt;frameCost=frameCost*.98+raw*1000*.02;if(frameCost>32&&elapsed>8&&!qualityReduced){renderer.setPixelRatio(1);renderer.shadowMap.enabled=false;qualityReduced=true;resize();}
if(state.mode==='countdown'){state.countdown-=dt;const n=Math.ceil(state.countdown);if(n!==lastCount){lastCount=n;if(n>0)audio.play('countdown');}$('countdown').textContent=n>0?n:'GO';if(state.countdown<=0){setMode('racing');audio.play('go');toast('GO!  HOLD W OR ↑ TO ACCELERATE',2.2);}}
if(state.mode==='racing'){let remaining=dt;while(remaining>0){const step=Math.min(remaining,1/60);updateRace(step);remaining-=step;if(state.mode!=='racing')break;}}
if(state.mode!=='paused'){world.update(elapsed);tickParticles(dt);updateCamera(dt);}
if(toastTime>0&&state.mode!=='paused'){toastTime-=dt;if(toastTime<=0)$('toast').hidden=true;}
audio.update({speed:state.speed,maxSpeed:104,throttle:controls.accelerate,nitro:state.boost,drift:state.drifting,active:state.mode==='racing'});if(state.mode!=='menu')updateHUD();renderSpeedFX(elapsed);cinematic.render(scene,camera,{boost:state.boost?1:0,speed:state.speed*3.6,time:elapsed});}

$('start-button').addEventListener('click',resetRace);$('retry-button').addEventListener('click',resetRace);$('restart-button').addEventListener('click',resetRace);$('pause-button').addEventListener('click',pauseRace);$('resume-button').addEventListener('click',pauseRace);$('menu-button').addEventListener('click',showMenu);$('result-menu').addEventListener('click',showMenu);$('help-button').addEventListener('click',()=>{$('help-panel').hidden=false;});$('help-close').addEventListener('click',()=>{$('help-panel').hidden=true;});
function toggleSound(){muted=!muted;audio.setMuted(muted);$('sound-button').setAttribute('aria-pressed',String(!muted));$('sound-button').setAttribute('aria-label',muted?'Enable sound':'Mute sound');$('sound-button').classList.toggle('is-muted',muted);$('sound-button').title=muted?'Sound off (M)':'Sound on (M)';let label=$('sound-label');if(label)label.textContent=muted?'SOUND OFF':'SOUND ON';}
$('sound-button').addEventListener('click',toggleSound);$('fullscreen-button').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.',2);}});
window.addEventListener('keydown',e=>{if(keys[e.code]){e.preventDefault();controls[keys[e.code]]=true;}if(e.repeat)return;if(e.code==='Escape'){if(!$('help-panel').hidden)$('help-panel').hidden=true;else pauseRace();}if(e.code==='KeyP')pauseRace();if(e.code==='KeyR'&&state.mode!=='menu')resetRace();if(e.code==='KeyM')toggleSound();if(e.code==='Enter'&&state.mode==='menu')resetRace();});
window.addEventListener('keyup',e=>{if(keys[e.code]){e.preventDefault();controls[keys[e.code]]=false;}});
window.addEventListener('blur',()=>{clearInputs();if(['racing','countdown'].includes(state.mode))pauseRace();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInputs();if(['racing','countdown'].includes(state.mode))pauseRace();}});
for(const b of document.querySelectorAll('[data-control]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);controls[b.dataset.control]=true;b.classList.add('pressed');});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,e=>{e.preventDefault();controls[b.dataset.control]=false;b.classList.remove('pressed');});}
document.addEventListener('contextmenu',e=>e.preventDefault());
showMenu();const initial=world.sample(0);camera.position.copy(initial.position).addScaledVector(initial.tangent,-10.5).addScaledVector(initial.right,-8.5).add(new THREE.Vector3(0,4.4,0));cameraLook.copy(initial.position);updateCamera(1);requestAnimationFrame(frame);
// Read-only diagnostics make genuine race outcomes and rendering health inspectable.
window.raceDiagnostics=()=>({mode:state.mode,distance:state.s,x:state.x,xv:state.xv,traffic:traffic.map(t=>({s:t.s,x:t.x})),rivals:rivals.map(r=>({s:r.s,x:r.x})),pickupLocations:world.pickups.map(p=>({s:p.s,x:p.x,active:p.active})),trackLength:world.length,speed:state.speed,nitro:state.nitro,checkpoint:state.checkpoint,time:state.time,position:1+rivals.filter(r=>r.s>state.s).length,airborne:state.air,damage:state.damage,drifting:state.drifting,pickups:world.pickups.filter(p=>!p.active).length,ramps:world.ramps.map(r=>({...r})),calls:renderer.info.render.calls,triangles:renderer.info.render.triangles,qualityReduced,inputs:{...controls}});
